package com.saumyasolar.repo;import com.saumyasolar.domain.InventoryBalance;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import java.util.List;import java.util.Optional;import java.util.UUID;
public interface InventoryBalanceRepository extends JpaRepository<InventoryBalance,UUID>{List<InventoryBalance> findByTenantIdOrderByWarehouseIdAscProductIdAsc(UUID tenantId);Optional<InventoryBalance> findByTenantIdAndWarehouseIdAndProductId(UUID tenantId,UUID warehouseId,UUID productId);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select b from InventoryBalance b where b.tenantId=:tenantId and b.warehouseId=:warehouseId and b.productId=:productId") Optional<InventoryBalance> findForUpdate(@Param("tenantId") UUID tenantId,@Param("warehouseId") UUID warehouseId,@Param("productId") UUID productId);}